,p_name=>'CANCEL_MODAL'
,p_display_name=>'Cancel modal page'
,p_category=>'EFFECT'
,p_image_prefix => nvl(wwv_flow_application_install.get_static_plugin_file_prefix('DYNAMIC ACTION','CANCEL_MODAL'),'')
,p_plsql_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'FUNCTION FK_CANCEL_MODAL_PAGE (p_dynamic_action IN APEX_PLUGIN.T_DYNAMIC_ACTION,',
'                               p_plugin         IN APEX_PLUGIN.T_PLUGIN ',
'                              )',
'RETURN APEX_PLUGIN.T_DYNAMIC_ACTION_RENDER_RESULT IS',
'',
'   rResult APEX_PLUGIN.T_DYNAMIC_ACTION_RENDER_RESULT;',
'   vcCrlf  VARCHAR(2) := CHR(13)||CHR(10);',
'',
'BEGIN',
'  IF apex_application.g_debug THEN',
'      apex_plugin_util.debug_dynamic_action(',
'         p_plugin         => p_plugin,',
'         p_dynamic_action => p_dynamic_action ',
'      );',
'   END IF;',
'   ',
'      ',
'   rResult.javascript_function :=''function(){'' || vcCrlf ||',
'								 ''   if (this.browserEvent !== ''''load''''){'' || vcCrlf ||',
'								 ''		javascript:parent.$(parent.document).apex_modal_page(''''close'''');'' || vcCrlf ||',
'								 ''   }'' || vcCrlf ||',
'								 ''}'';',
'',
'   RETURN rResult;',
'    ',
'END;'))
,p_api_version=>1
,p_render_function=>'FK_CANCEL_MODAL_PAGE'
,p_substitute_attributes=>true
,p_version_scn=>14202095
,p_subscribe_plugin_settings=>true
,p_version_identifier=>'1.0'
);
end;
