wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(910651590509133454)
,p_validation_name=>'Validate templates'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE ',
'  bError BOOLEAN:=FALSE;',
'BEGIN',
'  FOR i IN 1..APEX_Application.g_f01.COUNT LOOP',
'    IF APEX_Application.g_f02(i) IS NULL THEN',
'      bError:=TRUE;',
'    ELSE',
'      APEX_COLLECTION.UPDATE_MEMBER_ATTRIBUTE(p_collection_name=>''JRXML'',',
'                                              p_seq            =>APEX_Application.g_f01(i),',
'                                              p_attr_number    =>11,',
'                                              p_attr_value     =>TO_NUMBER(APEX_Application.g_f02(i))',
'                                             );',
'    END IF;',
'    IF APEX_Application.g_f03(i) IS NULL THEN',
'      bError:=TRUE;',
'    ELSE',
'      APEX_COLLECTION.UPDATE_MEMBER_ATTRIBUTE(p_collection_name=>''JRXML'',',
'                                              p_seq            =>APEX_Application.g_f01(i),',
'                                              p_attr_number    =>12,',
'                                              p_attr_value     =>TO_NUMBER(APEX_Application.g_f03(i))',
'                                             );',
'    END IF;',
'    IF APEX_Application.g_f04(i) IS NULL THEN',
'      bError:=TRUE;',
'    ELSE',
'      APEX_COLLECTION.UPDATE_MEMBER_ATTRIBUTE(p_collection_name=>''JRXML'',',
'                                              p_seq            =>APEX_Application.g_f01(i),',
'                                              p_attr_number    =>13,',
'                                              p_attr_value     =>TO_NUMBER(APEX_Application.g_f04(i))',
'                                             );',
'    END IF;',
'    IF APEX_Application.g_f05(i) IS NULL THEN',
'      bError:=TRUE;',
'    ELSE',
'      APEX_COLLECTION.UPDATE_MEMBER_ATTRIBUTE(p_collection_name=>''JRXML'',',
'                                              p_seq            =>APEX_Application.g_f01(i),',
'                                              p_attr_number    =>14,',
'                                              p_attr_value     =>TO_NUMBER(APEX_Application.g_f05(i))',
'                                             );',
'    END IF;',
'    IF APEX_Application.g_f06(i) IS NULL THEN',
'      bError:=TRUE;',
'    ELSE',
'      APEX_COLLECTION.UPDATE_MEMBER_ATTRIBUTE(p_collection_name=>''JRXML'',',
'                                              p_seq            =>APEX_Application.g_f01(i),',
'                                              p_attr_number    =>15,',
'                                              p_attr_value     =>TO_NUMBER(APEX_Application.g_f06(i))',
'                                             );',
'    END IF;',
'  END LOOP;',
'  RETURN NOT bError;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>'You have to choose all templates.'
,p_when_button_pressed=>wwv_flow_imp.id(908063303921030785)
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
end;
